.php?','unactioned','',NULL,NULL),(394,50,'sirt-woo-2024-11-xss-admin','Dismiss','#','actioned','',NULL,NULL),(395,51,'paypal-braintree-sdk-depreciation-2025-02-20-button','Upgrade now','http://46.250.232.141:8632/wp-admin/wp-admin/plugins.php','actioned','',NULL,NULL),(396,52,'uk-vat-notice-button-2025-04-30','Learn more about this extension','https://wordpress.org/plugins/eu-vat-for-woocommerce/','actioned','',NULL,NULL),(397,53,'paypal-braintree-sdk-depreciation-2025-05-30-button','Update now','http://46.250.232.141:8632/wp-admin/wp-admin/plugins.php','unactioned','',NULL,NULL),(398,54,'woo-dotcom-course-2026-06-09','Visit the course','https://wordpress.com/support/courses/build-your-store-with-woocommerce/','actioned','',NULL,NULL),(399,55,'google-for-woocommerce-mapi-update-button','Update now','http://46.250.232.141:8632/wp-admin/plugins.php','unactioned','',NULL,NULL),(400,55,'google-for-woocommerce-mapi-update-dismiss','Dismiss','#','actioned','',NULL,NULL),(401,56,'wcpay_security_update_guidance','View update guidance','https://developer.woocommerce.com/?p=8771721','actioned','',NULL,NULL),(402,57,'review-feature-settings','Get started','http://46.250.232.141:8632/wp-admin/admin.php?page=wc-settings&tab=advanced&section=features','actioned','',NULL,NULL),(403,57,'learn-more','Learn more','https://woocommerce.com/document/customer-order-withdrawal/','unactioned','',NULL,NULL);
